#!/bin/bash

# Decode the event
EVENT_JSON=$(echo "" | base64 -d 2>/dev/null)

# Extract fields
TWEET_ID=$(echo "$EVENT_JSON" | sed -n 's/.*"id":"\([^"]*\)".*/\1/p')
USERNAME=$(echo "$EVENT_JSON" | sed -n 's/.*"username":"\([^"]*\)".*/\1/p')
CREATED_AT=$(echo "$EVENT_JSON" | sed -n 's/.*"created_at":"\([^"]*\)".*/\1/p')
URL=$(echo "$EVENT_JSON" | sed -n 's/.*"url":"\([^"]*\)".*/\1/p')

echo "Tweet ID: $TWEET_ID"
echo "Username: $USERNAME"
echo "Created: $CREATED_AT"
echo "URL: $URL"
echo ""
echo "Full text (first 500 chars):"
echo "$EVENT_JSON" | sed -n 's/.*"text":"\([^"]*\)".*/\1/p' | head -c 500
echo ""
echo ""
echo "Media:"
echo "$EVENT_JSON" | sed -n 's/.*"media":\[\([^]]*\).*/\1/p'
